use scrabble_score::*;

#[test]
fn lowercase_letter() {
    let input = "a";
    let output = score(input);
    let expected = 1;
    assert_eq!(output, expected);
}

#[test]
#[ignore]
fn uppercase_letter() {
    let input = "A";
    let output = score(input);
    let expected = 1;
    assert_eq!(output, expected);
}

